// Reponse VOLUMINEUSE : on renvoie tout l'objet, y compris des champs inutiles
// au client (mot de passe hache, historique complet, objets imbriques).
// Plus d'octets a serialiser, a transporter et a deserialiser.
{
  "id": "018f...",
  "nom": "Ada",
  "motDePasseHache": "$2b$12$...",
  "historiqueConnexions": [
    { "date": "2026-01-01T08:00:00Z", "ip": "10.0.0.1" }
  ],
  "preferences": { "theme": "sombre", "langue": "fr" }
}

// Reponse ALLEGEE : seulement les champs dont le client a besoin ici.
// Moins de CPU pour serialiser, moins d'octets sur le reseau.
{
  "id": "018f...",
  "nom": "Ada"
}

// Objet metier complet : beaucoup de champs, certains sensibles ou inutiles au client
public record Utilisateur(
    UUID id,
    String nom,
    String email,
    String motDePasseHache,
    List<Commande> commandes
) {}

// DTO cible : on expose seulement ce que la liste d'utilisateurs a besoin d'afficher.
// La serialisation produit un JSON court, sans champ sensible ni relation entiere.
public record UtilisateurResumeDto(
    UUID id,
    String nom
) {
    public static UtilisateurResumeDto depuis(Utilisateur u) {
        return new UtilisateurResumeDto(u.id(), u.nom());
    }
}
